const binaryKey = Object.keys(items[0].binary || {})[0];
if (!binaryKey) {
  throw new Error('No binary data found. Please upload a transcript file.');
}
const binaryData = items[0].binary[binaryKey];
const txtContent = Buffer.from(binaryData.data, 'base64').toString('utf-8');
const lines = txtContent.split('\n');
let transcriptWithTimestamps = [];
if (txtContent.startsWith('WEBVTT')) {
  let currentTimestamp = null;
  let currentText = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    const ts = line.match(/^(\d{2}:\d{2}:\d{2}\.\d{3}) --> (\d{2}:\d{2}:\d{2}\.\d{3})$/);
    if (ts) {
      if (currentTimestamp && currentText.length) {
        transcriptWithTimestamps.push(`[${currentTimestamp}] Unknown: ${currentText.join(' ').trim()}`);
      }
      currentTimestamp = ts[1];
      currentText = [];
    } else if (line !== '' && !line.startsWith('WEBVTT')) {
      currentText.push(line);
    }
  }
  if (currentTimestamp && currentText.length) {
    transcriptWithTimestamps.push(`[${currentTimestamp}] Unknown: ${currentText.join(' ').trim()}`);
  }
} else {
  let currentSpeaker = null;
  let currentTimestamp = null;
  let currentText = [];
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(/^\[([^\]]+)\]\s+(\d{2}:\d{2}:\d{2})(.*)$/);
    if (m) {
      if (currentSpeaker && currentTimestamp && currentText.length) {
        transcriptWithTimestamps.push(`[${currentTimestamp}] ${currentSpeaker}: ${currentText.join(' ').trim()}`);
      }
      currentSpeaker = m[1];
      currentTimestamp = m[2];
      currentText = m[3] ? [m[3].trim()] : [];
    } else if (lines[i].trim() !== '') {
      currentText.push(lines[i].trim());
    }
  }
  if (currentSpeaker && currentTimestamp && currentText.length) {
    transcriptWithTimestamps.push(`[${currentTimestamp}] ${currentSpeaker}: ${currentText.join(' ').trim()}`);
  }
}
items[0].json.transcriptWithTimestamps = transcriptWithTimestamps.join('\n');
return items;

